void URaidDirectorSubsystem::Initialize(FSubsystemCollectionBase& Collection){Super::Initialize(Collection);Scheduler=NewObject<URaidSchedulerComponent>(this);Debouncer=NewObject<URaidDebouncer>(this);Lifecycle=NewObject<URaidLifecycleComponent>(this);Budget=NewObject<USpawnBudgetTracker>(this);Capacity=NewObject<USpawnCapacityCalculator>(this);Limiter=NewObject<USpawnRequestLimiter>(this);Finder=NewObject<USpawnPositionFinder>(this);Balancer=NewObject<USpawnLoadBalancer>(this);Counter=NewObject<UPopulationCounter>(this);WaveStateMachine=NewObject<URaidWaveStateMachine>(this);FrameBudget=NewObject<URaidFrameBudget>(this);TimeBudget=NewObject<URaidTimeBudget>(this);FeedbackBus=NewObject<URaidFeedbackBus>(this);}
void URaidDirectorSubsystem::Deinitialize(){if(Context.bEventActive)CancelRaid(TEXT("WorldSubsystemDeinitialize"));Super::Deinitialize();}
TStatId URaidDirectorSubsystem::GetStatId()const{RETURN_QUICK_DECLARE_CYCLE_STAT(URaidDirectorSubsystem,STATGROUP_Tickables);}
void URaidDirectorSubsystem::ConfigureRaidAssets(URaidStageTableAsset*T,const TArray<UHordePlanAsset*>&P,UEnemyGroupLibrary*G,UEnemyLibrary*E){StageTable=T;AvailablePlans.Reset();for(UHordePlanAsset*Plan:P)if(Plan)AvailablePlans.Add(Plan);EnemyGroups=G;Enemies=E;}
void URaidDirectorSubsystem::Tick(float Dt){Super::Tick(Dt);if(!Context.bEventActive||!GetWorld())return;TimeBudget->BeginTick();FrameBudget->ResetFrame();ElapsedEventTime+=Dt;ProcessWaveTick(Dt);if(TimeBudget->HasTimeRemaining())ProcessSpawns(Dt);}
void URaidDirectorSubsystem::StartRaid(FName ID,ERaidEventType Type){if(!GetWorld()||ID.IsNone()||Context.bEventActive||!Debouncer->TryAcquireEventLock(ID,60.f))return;Context.Reset();Context.EventID=ID;Context.EventType=Type;Context.bEventActive=true;Context.EventStartTime=GetWorld()->GetTimeSeconds();ElapsedEventTime=0.f;BudgetWaveIndex=INDEX_NONE;CaptureContext();if(Context.Players.IsEmpty()){Context.bEventActive=false;Context.Lifecycle=ERaidLifecycleState::Cancelled;Debouncer->ReleaseEventLock(ID);return;}EvaluateDifficulty();BuildPlan();if(!CurrentPlan||CurrentPlan->Waves.IsEmpty()){Context.bEventActive=false;Context.Lifecycle=ERaidLifecycleState::Cancelled;Debouncer->ReleaseEventLock(ID);return;}WaveStateMachine->Initialize(CurrentPlan->Waves.Num());BudgetWaveIndex=0;Budget->Initialize(CurrentPlan->Waves[0].TotalCount);Capacity->WaveCapacity=CurrentPlan->Waves[0].MaxAlive;Lifecycle->BeginEvent(Context);OnEventStarted.Broadcast(ID);FRaidFeedbackEvent Event;Event.Type=Type;Event.SourceModule=TEXT("Trigger");Event.TargetModule=TEXT("Difficulty");Event.NumericData.Add(TEXT("DifficultyScore"),(float)Context.DifficultyScore);FeedbackBus->Publish(TEXT("RaidStarted"),Event);}
void URaidDirectorSubsystem::EndRaid(){if(!Context.bEventActive)return;const FName ID=Context.EventID;Context.bEventActive=false;Lifecycle->EndEvent(Context);Debouncer->ReleaseEventLock(ID);OnEventEnded.Broadcast(ID);}
void URaidDirectorSubsystem::CancelRaid(FName Reason){if(!Context.bEventActive)return;const FName ID=Context.EventID;Context.bEventActive=false;Lifecycle->CancelEvent(Context,Reason);Debouncer->ReleaseEventLock(ID);OnEventEnded.Broadcast(ID);}
void URaidDirectorSubsystem::CaptureContext(){Context.Players.Empty();if(!GetWorld())return;for(FConstPlayerControllerIterator It=GetWorld()->GetPlayerControllerIterator();It;++It){APlayerController*PC=It->Get();if(!PC)continue;APawn*Pawn=PC->GetPawn();if(!Pawn)continue;FPlayerStateSnapshot S;S.PlayerId=PC->GetUniqueID();S.Location=Pawn->GetActorLocation();S.bIsAlive=true;if(APlayerState*PS=PC->GetPlayerState<APlayerState>())S.Level=1;Context.Players.Add(S);}Context.CapturedTime=GetWorld()->GetTimeSeconds();Context.World.InGameTime=Context.CapturedTime;Context.World.WorldMultiplier=1.f;}
void URaidDirectorSubsystem::EvaluateDifficulty(){if(!StageTable){Context.DifficultyStage=0;Context.DifficultyScore=0;return;}TArray<int32> Scores;for(const FPlayerStateSnapshot&P:Context.Players)Scores.Add(URaidDifficultyScorer::ComputeSingleScore(P.Level,P.SurvivalTime*StageTable->SurvivalTimeMultiplier,P.DeathCount*StageTable->DeathPenaltyFactor,StageTable->LevelMultiplier));Scores.Sort([](int32 A,int32 B){return A>B;});Context.DifficultyScore=URaidDifficultyScorer::ComputePartyScore(Scores,StageTable->PartyWeightFirst,StageTable->PartyWeightDecay);Context.DifficultyStage=URaidStageSelector::FindNearestStage(Context.DifficultyScore,StageTable);Context.bScoreFrozen=true;}
void URaidDirectorSubsystem::BuildPlan(){TArray<UHordePlanAsset*> PlanPointers;for(UHordePlanAsset* Plan:AvailablePlans)if(Plan)PlanPointers.Add(Plan);CurrentPlan=UHordePlanSelector::SelectPlanForStage(Context.DifficultyStage,PlanPointers);Context.bPlanFrozen=CurrentPlan!=nullptr;if(!CurrentPlan)return;if(StageTable)if(const FRaidStageConfig*C=StageTable->FindStageConfig(Context.DifficultyStage)){Capacity->EventCapacity=C->Budget.ConcurrentPopulation;Capacity->GlobalCapacity=FMath::Max(C->Budget.ConcurrentPopulation,C->Budget.ConcurrentPopulation*2);}}
void URaidDirectorSubsystem::ProcessWaveTick(float Dt){if(!CurrentPlan||!WaveStateMachine||!CurrentPlan->Waves.IsValidIndex(WaveStateMachine->CurrentWaveIndex))return;const int32 PreviousIndex=WaveStateMachine->CurrentWaveIndex;const FWavePlan&Wave=CurrentPlan->Waves[PreviousIndex];WaveStateMachine->IntermissionDuration=Wave.Intermission;WaveStateMachine->Tick(GetWorld()->GetTimeSeconds(),Budget->GetRemainingBudget(),Counter->GetLiveCount(),Wave.Duration);if(WaveStateMachine->CurrentWaveIndex!=PreviousIndex){const int32 NewIndex=WaveStateMachine->CurrentWaveIndex;if(CurrentPlan->Waves.IsValidIndex(NewIndex)){const FWavePlan&Next=CurrentPlan->Waves[NewIndex];Budget->Initialize(Next.TotalCount);Capacity->WaveCapacity=Next.MaxAlive;BudgetWaveIndex=NewIndex;OnWaveChanged.Broadcast(NewIndex,CurrentPlan->Waves.Num());FRaidFeedbackEvent E;E.Type=Context.EventType;E.SourceModule=TEXT("WaveState");E.TargetModule=TEXT("Budget");E.NumericData.Add(TEXT("WaveIndex"),(float)NewIndex);FeedbackBus->Publish(TEXT("WaveChanged"),E);}}if(WaveStateMachine->IsComplete())EndRaid();}
void URaidDirectorSubsystem::ProcessSpawns(float Dt){if(!CurrentPlan||WaveStateMachine->CurrentState!=EWaveState::Producing||!EnemyGroups||!Enemies)return;const int32 WI=WaveStateMachine->CurrentWaveIndex;if(!CurrentPlan->Waves.IsValidIndex(WI))return;const FWavePlan&Wave=CurrentPlan->Waves[WI];Capacity->WaveCapacity=Wave.MaxAlive;const int32 Free=Capacity->ComputeFreeCapacity(Counter->GetLiveCount());int32 Request=Limiter->ComputeSpawnRequest(Budget->GetRemainingBudget(),Free);/* FrameBudget and TimeBudget enforce per-frame work limits; detailed rate shaping is a follow-up tuning pass. */if(Request<=0)return;const TArray<FWeightedEntry> Pool=UHordeGroupResolver::ResolveGroup(Wave.GroupID,EnemyGroups);if(Pool.IsEmpty())return;FVector Target=FVector::ZeroVector;for(const FPlayerStateSnapshot&P:Context.Players)if(P.bIsAlive){Target=P.Location;break;}for(int32 I=0;I<Request&&TimeBudget->HasTimeRemaining();++I){if(!FrameBudget->TryConsumeSpawn())break;const FName EnemyID=UHordeCompositionPicker::PickWeightedEnemy(Pool);const FEnemyDefinition*Def=Enemies->FindEnemy(EnemyID);if(!Def||!Def->EnemyClass)continue;const FVector Pos=Finder->FindValidSpawnPosition(GetWorld(),Target);if(Pos.IsZero())continue;FActorSpawnParameters Params;Params.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;AActor*Enemy=GetWorld()->SpawnActor<AActor>(Def->EnemyClass,Pos,FRotator::ZeroRotator,Params);if(!Enemy)continue;Budget->OnSpawned();Counter->OnEntitySpawned(Enemy,EnemyID);Enemy->OnDestroyed.AddDynamic(this,&URaidDirectorSubsystem::HandleEnemyDestroyed);OnEnemySpawned.Broadcast(Enemy);Context.Lifecycle=ERaidLifecycleState::Active;}}

void URaidDirectorSubsystem::HandleEnemyDestroyed(AActor* Destroyed){if(Counter)Counter->OnEntityRemoved(Destroyed);OnEnemyDied.Broadcast(Destroyed);}
